API Gateway Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the API Gateway Container container

Container_Boundary(api_gateway_container, "API Gateway Container") {
    Component(Envoy Proxy Router, "Envoy Proxy Router", "Envoy Proxy", "Handles single entry point routing, TLS 1.3 termination, and edge schema validation.")
    Component(Rate Limiter, "Rate Limiter", "Redis, TCP / Redis Protocol", "Manages rate-limiting state and distributed caching to ensure high availability and performance.")
}

Rel(Envoy Proxy Router, Rate Limiter, "Queries and updates rate-limiting state", "TCP / Redis Protocol")

@enduml

Read-Model / Query Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("ReadModel___Query_Container", "Read-Model / Query Container") {
    Component(Query_Controller, "Query Controller", "CQRS Pattern / REST API", "Handles incoming read requests and routes queries for EMR workflows.")
    Component(Query_Service, "Query Service", "Business Logic Layer", "Implements business logic for retrieving and processing read-model data.")
    Component(Cache_Manager, "Cache Manager", "Redis / TCP", "Implements the cache-aside pattern for low-latency data retrieval.")
    Component(Event_Synchronization_Handler, "Event Synchronization Handler", "AMQP / Kafka", "Synchronizes event streams from the message broker to update read models.")
}

Rel(Query_Controller, Query_Service, "Delegates query execution")
Rel(Query_Service, Cache_Manager, "Retrieves cached state via cache-aside pattern")
Rel(Event_Synchronization_Handler, Query_Service, "Updates read models from event streams")

@enduml

Background Worker Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Background Worker Container container

Container_Boundary("Background Worker Container", "Background Worker Container") {
    Component("Task Consumer Component", "Task Consumer Component", "[e.g., Kafka Consumer / RabbitMQ Consumer]", "Consumes asynchronous tasks and messages from the message broker.")
    Component("Audit Dispatcher Component", "Audit Dispatcher Component", "[e.g., HTTPS Client]", "Sends scrubbed audit logs to the centralized audit logging service.")
}

Rel("Task Consumer Component", "Audit Dispatcher Component", "Forwards processed event data for secure logging", "HTTPS/TLS")

@enduml

Data Archival & Migration Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(data_archival_migration_container, "Data Archival & Migration Container") {
    Component(Archival_Controller, "Archival Controller", "Containerized Microservice / Python / Go", "Triggers and manages asynchronous data offloading workflows for long-term 10-year retention.")
    Component(Migration_Processor, "Migration Processor", "Apache Parquet / Avro / Schema Registry", "Executes batch processing, serialization, and write-verify-delete lifecycles for EMR records.")
    Component(Cryptographic_Verification_Service, "Cryptographic Verification Service", "TLS 1.3 / SHA-256 / Cryptographic Manifests", "Ensures data integrity during storage transfer by verifying checksums and manifest authenticity.")
}

System_Ext(DR_Storage_Targets, "DR Storage Targets", "Air-gapped DR storage targets for long-term retention.")

Rel(Archival_Controller, Migration_Processor, "Triggers batch offloading and data serialization workflows")
Rel(Migration_Processor, Cryptographic_Verification_Service, "Generates cryptographic checksums and validates transfers")
Rel(Cryptographic_Verification_Service, DR_Storage_Targets, "Transfers encrypted data using TLS 1.3 with SHA-256 checksums", "TLS 1.3 / SHA-256")

@enduml

Session & State Management Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component Diagram for Session & State Management Container

Container_Boundary(session_state_management_container, "Session & State Management Container") {
    Component(Distributed_Locking_Manager, "Distributed Locking Manager", "Redis Enterprise", "Provides high-availability distributed locking for clinical workflows.")
    Component(Session_Management_Service, "Session Management Service", "Redis Enterprise", "Manages user and system sessions across hybrid-cloud operations.")
    Component(Rate_Limiter, "Rate Limiter", "Redis Enterprise", "Handles rate limiting and protects upstream core domain services.")
    Component(Active_Active_Replication_Engine, "Active-Active Replication Engine", "Redis Enterprise", "Replicates state between on-prem Kubernetes and eu-central-1.")
}

Rel(Session_Management_Service, Distributed_Locking_Manager, "Coordinates distributed locks for concurrent operations", "TCP / Lettuce/ioredis")
Rel(Active_Active_Replication_Engine, Session_Management_Service, "Synchronizes state across multi-region deployments", "Active-Active Replication Protocol")

@enduml

